using namespace [ftxui](namespaceftxui.html);

// Define the document structure

[Element](namespaceftxui.html#a2bc31f2d685189e5c61d2293a1f51b4f) document = vbox({

text("FTXUI Getting Started") | bold | center,

separator(),

hbox({

text("Left Panel") | border,

vbox({

text("Main Content Area") | flex,

separator(),

text("Footer Information") | dim,

}) | border | flex,

