+    std::ranges::sort(book_paths, {}, [](const std::filesystem::path& path) {
+        return path.string();
+    });
+
+    size_t loaded = 0;
+    for (const std::filesystem::path& path : book_paths) {
+        Result<Book> book = Book::create(path.string());
+        if (!book) {
+            return std::unexpected(book.error());
+        }
+
+        add_book(std::move(*book));
+        ++loaded;
+    }
+
+    return loaded;
+}
+
+void SearchEngine::add_book(Book book) {
+    const size_t book_id = books.size();
+
+    for (size_t line_id = 0; line_id < book.lines.size(); ++line_id) {
+        const std::vector<std::string> words = tokenize(book.lines[line_id]);
+        for (size_t word_idx = 0; word_idx < words.size(); ++word_idx) {
+            const std::string& word = words[word_idx];
+            inverted_index[word].emplace_back(Index{
+                .book_id = book_id,
+                .chapter_id = 0,
+                .line = line_id,
+                .word_idx = word_idx,
+            });
+            ++word_counts[word];
+        }
+    }
+
+    books.push_back(std::move(book));
+}
+
+SearchResponse SearchEngine::search_with_context(const SearchRequest& request) const {
+    Option<std::vector<Index>> matches;
+
+    switch (request.mode) {
+        case SearchMode::Or:
+            matches = search_or(request.query);
+            break;
+        case SearchMode::And:
+            matches = search_and(request.query);
+            break;
+        case SearchMode::Phrase:
+            matches = search_phrase(request.query);
+            break;
+        case SearchMode::Not:
+            matches = search_not(request.query);
+            break;
+        case SearchMode::Near:
+            matches = search_near(request.near_left, request.near_right, request.near_distance);
+            break;
+    }
+
+    if (!matches) {
+        return {};
+    }
+
+    SearchResponse response;
+    response.hits.reserve(matches->size());
+
+    for (const Index& index : *matches) {
+        if (index.book_id >= books.size()) {
+            continue;
+        }
+
+        response.hits.push_back(SearchHit{
+            .index = index,
+            .book_name = books[index.book_id].name,
+            .line = index.line + 1,
+            .context = get_context(index),
+        });
+    }
+
+    return response;
+}
+
+Option<std::vector<Index>> SearchEngine::search(std::string_view query) const {
+    return search_or(query);
+}
+
+Option<std::vector<Index>> SearchEngine::search_or(std::string_view query) const {
+    std::vector<Index> matches;
+
+    for (const std::string& word : tokenize(query)) {
+        const auto found = inverted_index.find(word);
+        if (found != inverted_index.end()) {
+            matches.insert(matches.end(), found->second.begin(), found->second.end());
+        }
+    }
+
+    if (matches.empty()) {
+        return std::nullopt;
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+
+    return matches;
+}
+
+Option<std::vector<Index>> SearchEngine::search_and(std::string_view query) const {
+    std::vector<std::string> words;
+    std::unordered_set<std::string> seen_words;
+
+    for (std::string& word : tokenize(query)) {
+        if (seen_words.insert(word).second) {
+            words.emplace_back(std::move(word));
+        }
+    }
+
+    if (words.empty()) {
+        return std::nullopt;
+    }
+
+    std::unordered_map<size_t, size_t> book_match_counts;
+
+    for (const std::string& word : words) {
+        const auto found = inverted_index.find(word);
+        if (found == inverted_index.end()) {
+            return std::nullopt;
+        }
+
+        std::unordered_set<size_t> matched_books;
+        for (const Index& index : found->second) {
+            matched_books.emplace(index.book_id);
+        }
+
+        for (size_t book_id : matched_books) {
+            book_match_counts[book_id]++;
+        }
+    }
+
+    std::unordered_set<size_t> matched_books;
+    for (const auto& [book_id, count] : book_match_counts) {
+        if (count == words.size()) {
+            matched_books.insert(book_id);
+        }
+    }
+
+    if (matched_books.empty()) {
+        return std::nullopt;
+    }
+
+    std::vector<Index> matches;
+    for (const std::string& word : words) {
+        const auto& indices = inverted_index.at(word);
+
+        for (const Index& index : indices) {
+            if (matched_books.contains(index.book_id)) {
+                matches.push_back(index);
+            }
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+
+    return matches;
+}
+
+Option<std::vector<Index>> SearchEngine::search_phrase(std::string_view query) const {
+    const std::vector<std::string> words = tokenize(query);
+    if (words.empty()) {
+        return std::nullopt;
+    }
+
+    const auto first_word = inverted_index.find(words.front());
+    if (first_word == inverted_index.end()) {
+        return std::nullopt;
+    }
+
+    std::vector<Index> matches;
+    for (const Index& start : first_word->second) {
+        std::vector<Index> phrase_match{start};
+        bool is_phrase = true;
+
+        for (size_t offset = 1; offset < words.size(); ++offset) {
+            const auto found = inverted_index.find(words[offset]);
+            if (found == inverted_index.end()) {
+                return std::nullopt;
+            }
+
+            const auto next = std::ranges::find_if(found->second, [&](const Index& index) {
+                return index.book_id == start.book_id && index.chapter_id == start.chapter_id &&
+                       index.line == start.line && index.word_idx == start.word_idx + offset;
+            });
+
+            if (next == found->second.end()) {
+                is_phrase = false;
+                break;
+            }
+
+            phrase_match.push_back(*next);
+        }
+
+        if (is_phrase) {
+            matches.insert(matches.end(), phrase_match.begin(), phrase_match.end());
+        }
+    }
+
+    if (matches.empty()) {
+        return std::nullopt;
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+    return matches;
+}
+
+Option<std::vector<std::string>> SearchEngine::get_top_words(size_t nums) const {
+    using namespace std;
+
+    if (nums > word_counts.size()) {
+        return std::nullopt;
+    }
+
+    vector<pair<string, size_t>> counts;
+    counts.reserve(word_counts.size());
+
+    for (const auto& [word, count] : word_counts) {
+        counts.emplace_back(word, count);
+    }
+
+    ranges::sort(counts, {}, [](const auto& item) {
+        return std::pair{static_cast<size_t>(-item.second), item.first};
+    });
+
+    auto words = counts | views::take(nums) |
+                 views::transform([](auto& item) { return std::move(item.first); }) |
+                 ranges::to<vector<string>>();
+
+    return words;
+}
+
+Option<std::vector<std::string>> SearchEngine::get_books() const {
+    using namespace std;
+    return this->books | views::transform([](auto& item) { return item.name; }) |
+           ranges::to<vector<string>>();
+}
+
+Option<std::vector<Index>> SearchEngine::search_not(std::string_view query) const {
+    const std::vector<std::string> words = tokenize(query);
+    if (words.empty()) {
+        return std::nullopt;
+    }
+
+    const auto first_word = inverted_index.find(words.front());
+    if (first_word == inverted_index.end()) {
+        return std::nullopt;
+    }
+
+    std::unordered_set<size_t> matched_books;
+    for (const Index& index : first_word->second) {
+        matched_books.insert(index.book_id);
+    }
+
+    for (auto word = std::next(words.begin()); word != words.end(); ++word) {
+        const auto found = inverted_index.find(*word);
+        if (found == inverted_index.end()) {
+            continue;
+        }
+
+        for (const Index& index : found->second) {
+            matched_books.erase(index.book_id);
+        }
+    }
+
+    if (matched_books.empty()) {
+        return std::nullopt;
+    }
+
+    std::vector<Index> matches;
+    for (const Index& index : first_word->second) {
+        if (matched_books.contains(index.book_id)) {
+            matches.push_back(index);
+        }
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+
+    return matches;
+}
+
+Option<std::vector<Index>> SearchEngine::search_near(
+    std::string_view key1, std::string_view key2, size_t dis) const {
+    const std::string word1 = normalize_word(key1);
+    const std::string word2 = normalize_word(key2);
+    if (word1.empty() || word2.empty()) {
+        return std::nullopt;
+    }
+
+    const auto first_word = inverted_index.find(word1);
+    const auto second_word = inverted_index.find(word2);
+    if (first_word == inverted_index.end() || second_word == inverted_index.end()) {
+        return std::nullopt;
+    }
+
+    std::vector<Index> matches;
+
+    for (const Index& first : first_word->second) {
+        for (const Index& second : second_word->second) {
+            if (first.book_id != second.book_id || first.chapter_id != second.chapter_id ||
+                first.line != second.line) {
+                continue;
+            }
+
+            const size_t distance = first.word_idx > second.word_idx
+                                        ? first.word_idx - second.word_idx
+                                        : second.word_idx - first.word_idx;
+            if (distance <= dis) {
+                matches.push_back(first);
+                matches.push_back(second);
+            }
+        }
+    }
+
+    if (matches.empty()) {
+        return std::nullopt;
+    }
+
+    std::ranges::sort(matches, {}, cmpr);
+
+    return matches;
+}
+
+Context SearchEngine::get_context(const Index& idx) const {
+    if (idx.book_id >= books.size()) {
+        return {};
+    }
+    const Book& book = books[idx.book_id];
+
+    if (idx.line >= book.lines.size() || is_blank_line(book.lines[idx.line])) {
+        return {};
+    }
+    size_t cur_begin = idx.line;
+
+    while (cur_begin > 0 && !is_blank_line(book.lines[cur_begin - 1])) {
+        cur_begin--;
+    }
+
+    size_t cur_end = idx.line + 1;
+    while (cur_end < book.lines.size() && !is_blank_line(book.lines[cur_end])) {
+        cur_end++;
+    }
+
+    Context context{
+        .cur = join_lines(book.lines, cur_begin, cur_end),
+    };
+
+    size_t prev_end = cur_begin;
+    while (prev_end > 0 && is_blank_line(book.lines[prev_end - 1])) {
+        --prev_end;
+    }
+
+    size_t prev_begin = prev_end;
+    while (prev_begin > 0 && !is_blank_line(book.lines[prev_begin - 1])) {
+        --prev_begin;
+    }
+
+    if (prev_begin < prev_end) {
+        context.prev = join_lines(book.lines, prev_begin, prev_end);
+    }
+
+    size_t next_begin = cur_end;
+    while (next_begin < book.lines.size() && is_blank_line(book.lines[next_begin])) {
+        ++next_begin;
+    }
+
+    size_t next_end = next_begin;
+    while (next_end < book.lines.size() && !is_blank_line(book.lines[next_end])) {
+        ++next_end;
+    }
+
+    if (next_begin < next_end) {
+        context.next = join_lines(book.lines, next_begin, next_end);
+    }
+
+    return context;
+}

